35:     for (let y=-Math.ceil(ry); y<=ry; y++){
36:       const hw = Math.floor(rx*Math.sqrt(Math.max(0,1-(y*y)/(ry*ry))));
37:       c.fillRect(Math.round(cx-hw), Math.round(cy+y), hw*2+1, 1);
38:     }
39:   },
40:   ring(c,cx,cy,rx,ry,col,w=2){ // outlined ellipse by layered ellipses
41:     PX.ell(c,cx,cy,rx,ry,col);
42:     PX.ell(c,cx,cy,rx-w,ry-w,'__clear__');
43:   },
44:   tri(c,x1,y1,x2,y2,x3,y3,col){
45:     c.fillStyle=col;
46:     const minY=Math.floor(Math.min(y1,y2,y3)), maxY=Math.ceil(Math.max(y1,y2,y3));
47:     for (let y=minY;y<=maxY;y++){
48:       const xs=[];
49:       const edges=[[x1,y1,x2,y2],[x2,y2,x3,y3],[x3,y3,x1,y1]];
50:       for(const [ax,ay,bx,by] of edges){
51:         if ((y>=ay&&y<=by)||(y>=by&&y<=ay)){
52:           if (by===ay) continue;
53:           xs.push(ax+(bx-ax)*((y-ay)/(by-ay)));
54:         }
55:       }
56:       if (xs.length>=2){ const xa=Math.round(Math.min(...xs)), xb=Math.round(Math.max(...xs)); c.fillRect(xa,y,xb-xa+1,1); }
57:     }
58:   },
59:   line(c,x1,y1,x2,y2,col,w=2){
60:     const dx=x2-x1, dy=y2-y1; const steps=Math.max(Math.abs(dx),Math.abs(dy),1);
61:     c.fillStyle=col;
62:     for(let i=0;i<=steps;i++){ const x=Math.round(x1+dx*i/steps), y=Math.round(y1+dy*i/steps); c.fillRect(x-Math.floor(w/2),y-Math.floor(w/2),w,w); }
63:   }
64: };
