import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
const runtime = '/home/runner/.local/share/omgithub-playwright';
const require = createRequire(`${runtime}/package.json`);
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(`${runtime}/linux.json`, 'utf8'));
const browser = await chromium.launch(config.browser.launchOptions);
const page = await browser.newPage({ viewport: { width: 390, height: 844 }, isMobile: true, hasTouch: true });
const errors = [];
page.on('pageerror', error => errors.push(error.message));
await page.goto('http://127.0.0.1:8765', { waitUntil: 'load' });
await page.waitForSelector('.menu-window');
const layout = await page.evaluate(() => ({
  controls: getComputedStyle(document.querySelector('#touch-controls')).display,
  frame: document.querySelector('#gameframe').getBoundingClientRect().toJSON(),
  controlsBox: document.querySelector('#touch-controls').getBoundingClientRect().toJSON(),
  viewport: { width: innerWidth, height: innerHeight },
  overflow: document.documentElement.scrollHeight > innerHeight
}));
await page.locator('.touch-confirm').tap();
await page.waitForSelector('.menu-starters');
await page.locator('.touch-confirm').tap();
await page.waitForSelector('#dialogue:not(.hidden)');
await page.locator('.touch-confirm').tap();
await page.waitForFunction(() => !document.querySelector('#dialogue').classList.contains('hidden'));
await page.locator('.touch-confirm').tap();
await page.waitForFunction(() => document.querySelector('#dialogue').classList.contains('hidden'));
const before = await page.evaluate(() => ({ x: World.state.x, y: World.state.y }));
const up = await page.locator('.touch-up').boundingBox();
await page.mouse.move(up.x + up.width / 2, up.y + up.height / 2);
await page.mouse.down();
await page.waitForTimeout(500);
await page.mouse.up();
const after = await page.evaluate(() => ({ x: World.state.x, y: World.state.y, held: Input.held.arrowup }));
await page.screenshot({ path: '/tmp/opencode/pokemon-mobile-game.jpg', type: 'jpeg', quality: 82 });
console.log(JSON.stringify({ layout, before, after, errors }, null, 2));
await browser.close();

